{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Practical therapy for everyday decisions</title>
  <meta name="description" content="Calm, clear-headed therapeutic support for the life you're living. Short packages and ongoing cohorts offered in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <svg width="0" height="0" style="position:absolute;left:-9999px;">
    <defs>
      <pattern id="sitePattern" patternUnits="userSpaceOnUse" width="40" height="40">
        <image href="assets/img/pattern.svg" x="0" y="0" width="40" height="40"/>
      </pattern>
    </defs>
  </svg>

  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/index.html">Start</a>
        <a href="/about.html">Who I Am</a>
        <a href="/specialties.html">Areas</a>
        <a href="/approach.html">Way I Work</a>
        <a href="/fees.html">Invest</a>
        <a href="/faq.html">Questions</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" aria-label="Open menu">☰</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero reveal" id="hero">
      <div class="wrap">
        <h1>{{BUSINESS_NAME}}</h1>
        <p class="lead">A measured, empathetic space for working through change — one careful step at a time.</p>
        <p class="tag">{{TAGLINE}}</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/about.html">Who I Am</a>
        </div>
      </div>
    </section>

    <!-- Offers (placed early for a different flow) -->
    <section class="offers reveal" id="offers">
      <div class="wrap">
        <h2>Programs & small cohorts</h2>
        <p>Short, focused packages and guided cohorts that center on practical change. Choose a direction and we’ll build a supportive, confidential plan together.</p>
        <div class="cards">
          <article class="card">
            <h3>Compass Short Series</h3>
            <p>4 sessions across 6 weeks: a clear map for a single decision, transition, or relationship question.</p>
            <div class="price">From $480</div>
          </article>
          <article class="card">
            <h3>Steady Path Cohort</h3>
            <p>6-week small group with weekly live sessions and practical tools — gentle momentum with peer reflection.</p>
            <div class="price">Cohort pricing</div>
          </article>
          <article class="card">
            <h3>Ongoing Focus</h3>
            <p>Monthly slots for regular clinical work—flexible cadence, consistent attention to your priorities.</p>
            <div class="price">Monthly plans</div>
          </article>
        </div>

        <div class="session-planner" aria-labelledby="planner-title">
          <h3 id="planner-title">Session Planner</h3>
          <p>Build a simple, personalized plan you can copy and bring to your first appointment.</p>
          <form id="planner-form">
            <label>First name (optional)
              <input type="text" name="name" placeholder="Your name">
            </label>
            <label>Main concern or goal
              <textarea name="concern" rows="3" placeholder="Briefly describe what you'd like to address"></textarea>
            </label>
            <div class="grid-2">
              <label>Sessions per month
                <select name="frequency">
                  <option value="1">1</option>
                  <option value="2" selected>2</option>
                  <option value="4">4</option>
                </select>
              </label>
              <label>Duration (weeks)
                <select name="duration">
                  <option value="4">4</option>
                  <option value="6" selected>6</option>
                  <option value="12">12</option>
                </select>
              </label>
            </div>
            <fieldset>
              <legend>Focus areas</legend>
              <label><input type="checkbox" name="focus" value="Decision-making"> Decision-making</label>
              <label><input type="checkbox" name="focus" value="Anxiety"> Anxiety & worry</label>
              <label><input type="checkbox" name="focus" value="Relationships"> Relationships</label>
              <label><input type="checkbox" name="focus" value="Transitions"> Life transitions</label>
            </fieldset>

            <div class="planner-actions">
              <button type="button" id="planner-generate" class="btn">Make plan</button>
              <button type="button" id="planner-copy" class="btn ghost">Copy plan</button>
            </div>
          </form>

          <label>Plan summary
            <textarea id="planner-output" rows="6" readonly placeholder="Your plan will appear here."></textarea>
          </label>
        </div>

      </div>
    </section>

    <!-- Framework -->
    <section class="framework reveal" id="framework">
      <div class="wrap">
        <h2>How I work</h2>
        <p>I combine evidence-informed clinical methods with practical skills training in a collaborative way. We track what helps and shift course when needed. You remain the expert in your life; my role is to clarify options and hold clinical boundaries.</p>
        <ul>
          <li>Confidential, individual clinical sessions</li>
          <li>Short packages for focused goals</li>
          <li>Small cohorts for shared learning</li>
        </ul>
      </div>
    </section>

    <!-- Story (testimonial-like, but clinician voice) -->
    <section class="story reveal" id="story">
      <div class="wrap">
        <h2>A clinician's note</h2>
        <p>I'm a licensed therapist offering private practice care in {{CITY}}, {{STATE}}. I work with adults facing life transitions, relationship questions, and persistent anxiety. Sessions are pragmatic and reflective — we attend to patterns and also to what you need now.</p>
        <p class="muted">Sessions are confidential within clinical and legal limits. If you are in crisis or at risk of harm, please contact local emergency services or your crisis line immediately.</p>
      </div>
    </section>

    <!-- Pricing (another order change) -->
    <section class="pricing reveal" id="pricing">
      <div class="wrap">
        <h2>Investment</h2>
        <p>Transparent fees with options to match intensity and time frame. Sliding scale is available for some slots — please ask.</p>
        <dl class="pricing-grid">
          <div>
            <dt>Single session (50 min)</dt>
            <dd>$140</dd>
          </div>
          <div>
            <dt>Compass Short Series (4 sessions)</dt>
            <dd>$480</dd>
          </div>
          <div>
            <dt>Steady Path Cohort</dt>
            <dd>Variable — cohort rate</dd>
          </div>
        </dl>
      </div>
    </section>

    <!-- Testimonials -->
    <section class="testimonials reveal" id="testimonials">
      <div class="wrap">
        <h2>What people say</h2>
        <blockquote>"Clear guidance without pressure — I left with a practical next step and felt listened to."</blockquote>
        <blockquote>"A steady, realistic approach that fit into my life."</blockquote>
      </div>
    </section>

    <!-- Call to action -->
    <section class="cta reveal" id="final-cta">
      <div class="wrap">
        <h2>Ready to start?</h2>
        <p>Whether you prefer a short series, cohort learning, or ongoing sessions, we'll design care that meets your needs. Reach out to schedule a time to talk about fit.</p>
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="contact-small">Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Confidential, thoughtful clinical care. Not a substitute for emergency services.</p>
      <p>Licensing, scope, and boundaries are discussed at intake. Confidentiality holds except where disclosure is required by law.</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
