{"path":"assets/css/styles.css","content":"/* Minimal reset */
:root{--primary:#6a4de8;--accent:#ffd166;--bg:#fcfbff;--muted:#667085;--wrap:1100px}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
body{background:var(--bg) url('/assets/img/pattern.svg');background-repeat:repeat;color:#1b1b20;line-height:1.5}
.wrap{max-width:var(--wrap);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));backdrop-filter:blur(4px);position:sticky;top:0;z-index:20;border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:1rem}
.brand{font-weight:700;color:var(--primary);text-decoration:none;font-size:1.25rem}
.main-nav{margin-left:auto;display:flex;align-items:center;gap:0.5rem}
.main-nav a{color:inherit;text-decoration:none;padding:0.5rem}
.main-nav .cta{background:var(--primary);color:white;border-radius:6px;padding:0.5rem 0.75rem}
.nav-toggle{display:none}

.hero{padding:4rem 0;background:linear-gradient(120deg,rgba(106,77,232,0.06),transparent)}
.hero h1{margin:0;font-size:2rem}
.lead{font-size:1.125rem;color:var(--muted)}
.hero-actions{margin-top:1rem;display:flex;gap:0.75rem}
.btn{display:inline-block;border-radius:8px;padding:0.6rem 1rem;border:1px solid rgba(0,0,0,0.06);cursor:pointer;background:white}
.btn.primary{background:var(--primary);color:white;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}

.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-top:1rem}
.card{background:white;padding:1rem;border-radius:10px;box-shadow:0 6px 18px rgba(22,22,30,0.04)}
.price{font-weight:700;margin-top:0.5rem;color:var(--primary)}

.session-planner{margin-top:1.5rem;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.9));padding:1rem;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
.session-planner form label{display:block;margin-bottom:0.5rem}
.session-planner input[type=text],.session-planner select,.session-planner textarea{width:100%;padding:0.5rem;border-radius:6px;border:1px solid #e6e9ef}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem}
fieldset{border:none;padding:0;margin:0 0 1rem 0}
fieldset label{display:inline-block;margin-right:0.75rem}
.planner-actions{display:flex;gap:0.5rem;margin-top:0.5rem}
#planner-output{margin-top:0.5rem;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}

.framework,.story,.pricing,.testimonials,.cta{padding:2.25rem 0}
.muted{color:var(--muted)}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:1rem}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:1.5rem 0;background:transparent}

/* Reveal animations */
.reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
.reveal.reveal-visible{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
}

/* Responsive */
@media (max-width:700px){
  .wrap{padding:1rem}
  .nav-toggle{display:inline-block}
  .main-nav a:not(.cta){display:none}
}

/* small utilities */
blockquote{background:white;padding:1rem;border-radius:8px;box-shadow:0 6px 12px rgba(22,22,30,0.04)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  'use strict';
  // Set year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Simple nav toggle for small screens
  var toggle = document.querySelector('.nav-toggle');
  if(toggle){
    toggle.addEventListener('click', function(){
      document.querySelector('.main-nav').classList.toggle('open');
    });
  }

  // Scroll-triggered reveal respecting prefers-reduced-motion
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var reveals = Array.prototype.slice.call(document.querySelectorAll('.reveal'));
  if(prefersReduced){
    reveals.forEach(function(el){ el.classList.add('reveal-visible'); });
  } else if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          entry.target.classList.add('reveal-visible');
          io.unobserve(entry.target);
        }
      });
    },{threshold:0.12});
    reveals.forEach(function(el){ io.observe(el); });
  } else {
    // Fallback: reveal all
    reveals.forEach(function(el){ el.classList.add('reveal-visible'); });
  }

  // Session Planner widget
  var form = document.getElementById('planner-form');
  var out = document.getElementById('planner-output');
  var btnGenerate = document.getElementById('planner-generate');
  var btnCopy = document.getElementById('planner-copy');

  function buildPlan(){
    if(!form || !out) return '';
    var fd = new FormData(form);
    var name = (fd.get('name')||'').trim();
    var concern = (fd.get('concern')||'').trim();
    var freq = fd.get('frequency') || '2';
    var duration = fd.get('duration') || '6';
    var focuses = fd.getAll('focus') || [];

    var lines = [];
    lines.push('Personalized Session Plan');
    lines.push('-------------------------');
    if(name) lines.push('Name: ' + name);
    lines.push('Primary concern: ' + (concern || 'Not specified'));
    lines.push('Sessions per month: ' + freq);
    lines.push('Planned duration (weeks): ' + duration);
    if(focuses.length){
      lines.push('Focus areas: ' + focuses.join(', '));
    } else {
      lines.push('Focus areas: To be decided in session');
    }
    lines.push('Suggested next step: Schedule an intake to clarify goals and discuss fit.');
    lines.push('\nNotes: This plan is a starting point for conversation with a clinician.');

    return lines.join('\n');
  }

  btnGenerate && btnGenerate.addEventListener('click', function(){
    var text = buildPlan();
    out.value = text;
    // save to localStorage as a convenience
    try{ localStorage.setItem('lastPlan', text); }catch(e){}
  });

  btnCopy && btnCopy.addEventListener('click', function(){
    if(!out.value){
      var txt = buildPlan();
      out.value = txt;
    }
    out.select();
    try{
      var ok = document.execCommand('copy');
      // Provide lightweight feedback
      var prev = btnCopy.textContent;
      btnCopy.textContent = ok ? 'Copied' : 'Copy';
      setTimeout(function(){ btnCopy.textContent = prev; }, 1600);
    }catch(e){
      // Fallback: show text to user
      window.prompt('Copy the plan below (Ctrl/Cmd+C):', out.value);
    }
  });

  // Try restore last plan
  try{
    var saved = localStorage.getItem('lastPlan');
    if(saved && out && !out.value) out.value = saved;
  }catch(e){}

})();"} 
